CREATE TABLE IF NOT EXISTS acceptance_criteria(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),deliverable_id UUID NOT NULL,description TEXT NOT NULL,test_method TEXT NOT NULL CHECK(test_method IN('INSPECTION','MEASUREMENT','DOCUMENT_REVIEW','FUNCTIONAL_TEST')),metric TEXT NOT NULL,tolerance JSONB NOT NULL,validator_role TEXT NOT NULL,retest_allowed BOOLEAN NOT NULL,max_retests INTEGER NOT NULL CHECK(max_retests>=0),status TEXT NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS success_metrics(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,kind TEXT NOT NULL CHECK(kind IN('KPI','SLA','QUALITY','TIMELINESS','OUTCOME','COST')),name TEXT NOT NULL,target_value NUMERIC NOT NULL,unit TEXT NOT NULL,direction TEXT NOT NULL CHECK(direction IN('HIGHER_IS_BETTER','LOWER_IS_BETTER')),weight_percent NUMERIC NOT NULL CHECK(weight_percent>0 AND weight_percent<=100),status TEXT NOT NULL CHECK(status IN('DRAFT','CONFIRMED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS dependencies(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,kind TEXT NOT NULL CHECK(kind IN('INTERNAL','EXTERNAL','VENDOR','CUSTOMER','REGULATORY','FUNDING')),description TEXT NOT NULL,owner_id UUID NOT NULL,due_date DATE NOT NULL,criticality TEXT NOT NULL CHECK(criticality IN('LOW','MEDIUM','HIGH','BLOCKING')),status TEXT NOT NULL CHECK(status IN('OPEN','RESOLVED')),created_at TIMESTAMPTZ NOT NULL DEFAULT now(),resolved_at TIMESTAMPTZ);
CREATE TABLE IF NOT EXISTS payment_trigger_rules(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),milestone_id UUID NOT NULL,name TEXT NOT NULL,rule_type TEXT NOT NULL CHECK(rule_type IN('MILESTONE_COMPLETION','DOD_PUBLISHED','ACCEPTANCE_PASSED','HYBRID')),required_dod_package_id UUID,required_acceptance_criterion_ids JSONB NOT NULL,amount_minor BIGINT NOT NULL CHECK(amount_minor>0),currency TEXT NOT NULL,status TEXT NOT NULL CHECK(status IN('DRAFT','ACTIVE','INACTIVE')),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS performance_baselines(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),blueprint_id UUID NOT NULL,milestone_id UUID NOT NULL UNIQUE,planned_start_date DATE NOT NULL,planned_due_date DATE NOT NULL,planned_budget_amount_minor BIGINT NOT NULL CHECK(planned_budget_amount_minor>0),planned_scope_item_count INTEGER NOT NULL,planned_quality_score NUMERIC NOT NULL,planned_risk_score NUMERIC NOT NULL,status TEXT NOT NULL CHECK(status='BASELINED'),created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS baseline_variances(id UUID PRIMARY KEY DEFAULT gen_random_uuid(),workspace_id UUID NOT NULL REFERENCES workspaces(id),baseline_id UUID NOT NULL REFERENCES performance_baselines(id),actual_start_date DATE,actual_due_date DATE,actual_cost_amount_minor BIGINT,actual_scope_item_count INTEGER,actual_quality_score NUMERIC,actual_risk_score NUMERIC,schedule_variance_days INTEGER NOT NULL,cost_variance_minor BIGINT NOT NULL,scope_variance_count INTEGER NOT NULL,recorded_by UUID NOT NULL,recorded_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS acceptance_criteria_deliverable_idx ON acceptance_criteria(workspace_id,deliverable_id);CREATE INDEX IF NOT EXISTS success_metrics_milestone_idx ON success_metrics(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS dependencies_milestone_status_idx ON dependencies(workspace_id,milestone_id,status);CREATE INDEX IF NOT EXISTS payment_trigger_rules_milestone_idx ON payment_trigger_rules(workspace_id,milestone_id);CREATE INDEX IF NOT EXISTS baseline_variances_baseline_idx ON baseline_variances(workspace_id,baseline_id);
ALTER TABLE acceptance_criteria ENABLE ROW LEVEL SECURITY;ALTER TABLE success_metrics ENABLE ROW LEVEL SECURITY;ALTER TABLE dependencies ENABLE ROW LEVEL SECURITY;ALTER TABLE payment_trigger_rules ENABLE ROW LEVEL SECURITY;ALTER TABLE performance_baselines ENABLE ROW LEVEL SECURITY;ALTER TABLE baseline_variances ENABLE ROW LEVEL SECURITY;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['acceptance_criteria','success_metrics','dependencies','payment_trigger_rules','performance_baselines','baseline_variances'] LOOP BEGIN EXECUTE format('CREATE POLICY %I ON %I USING(workspace_id=current_workspace_id() AND has_active_workspace_membership(workspace_id))',t||'_workspace',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
DO $$ DECLARE t TEXT;BEGIN FOREACH t IN ARRAY ARRAY['acceptance_criteria','success_metrics','payment_trigger_rules','performance_baselines','baseline_variances'] LOOP BEGIN EXECUTE format('CREATE TRIGGER %I BEFORE UPDATE OR DELETE ON %I FOR EACH ROW EXECUTE FUNCTION prevent_append_only_mutation()',t||'_append_only',t);EXCEPTION WHEN duplicate_object THEN NULL;END;END LOOP;END $$;
